  1	import 'package:flutter_bloc/flutter_bloc.dart';
  2	
  3	import '../../domain/repositories/entries_repository.dart';
  4	import 'meus_registros_state.dart';
  5	
  6	/// Drives `MeusRegistrosScreen` — calls `EntriesRepository.list()` directly
  7	/// (no use-case layer, matching this codebase's existing small-scope
  8	/// convention: `AccountSettingsCubit`/`AuthCubit`/`TextEntryCubit`). A
  9	/// `lazySingleton` (Code Map), like `AccountSettingsCubit` — long-lived, so
 10	/// the already-fetched pages survive leaving and re-entering
 11	/// `/meus-registros` within the same app session.
 12	class MeusRegistrosCubit extends Cubit<MeusRegistrosState> {
 13	  MeusRegistrosCubit(this._repository) : super(const MeusRegistrosLoading());
 14	
 15	  final EntriesRepository _repository;
 16	
 17	  /// A monotonic counter guarding against a stale in-flight call's result
 18	  /// landing after a newer call has already changed the state (e.g. the
 19	  /// user leaves and quickly re-enters `/meus-registros` while a slow
 20	  /// first request is still pending, or taps retry before the original
 21	  /// request resolves). Incremented at the start of every [loadFirstPage],
 22	  /// then captured locally before each `await` in [loadFirstPage]/
 23	  /// [_fetchMore] — a result whose captured generation no longer matches
 24	  /// this counter by the time it resolves is discarded rather than
 25	  /// emitted.
 26	  int _generation = 0;
 27	
 28	  /// `MeusRegistrosScreen.initState` calls this once, every mount — always
 29	  /// re-fetches from scratch rather than keeping a previous visit's page
 30	  /// around, since a new entry may have been saved (Insertion Modal, Epic
 31	  /// 3) since the last visit.
 32	  Future<void> loadFirstPage() async {
 33	    final generation = ++_generation;
 34	    emit(const MeusRegistrosLoading());
 35	    final result = await _repository.list();
 36	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: `close()`
 37	    // can race this awaited call (e.g. a fast app teardown mid-request) —
 38	    // `emit()` after `close()` would otherwise throw.
 39	    if (isClosed || generation != _generation) {
 40	      return;
 41	    }
 42	    result.match(
 43	      (failure) => emit(MeusRegistrosError(message: failure.message)),
 44	      (page) {
 45	        if (page.items.isEmpty) {
 46	          emit(const MeusRegistrosEmpty());
 47	          return;
 48	        }
 49	        emit(
 50	          MeusRegistrosLoaded(entries: page.items, nextCursor: page.nextCursor),
 51	        );
 52	      },
 53	    );
 54	  }
 55	
 56	  /// `MeusRegistrosScreen`'s scroll listener calls this near the list's
 57	  /// end. A no-op while not [MeusRegistrosLoaded], while
 58	  /// [MeusRegistrosLoaded.nextCursor] is already `null`, while a call is
 59	  /// already in flight, or — critically — once
 60	  /// [MeusRegistrosLoaded.loadMoreFailed] is already `true`: without that
 61	  /// last guard, a failed page's own footer swapping from a spinner to a
 62	  /// "Tentar novamente" button can shift the list's `maxScrollExtent`
 63	  /// just enough to leave the scroll position still inside the
 64	  /// pre-fetch-buffer zone, re-firing this same listener and retrying
 65	  /// forever — observed directly as an unbounded `pumpAndSettle` loop in
 66	  /// this screen's own widget test. Once failed, only an explicit
 67	  /// [retryLoadMore] (the footer's own button) tries again.
 68	  Future<void> loadMore() => _fetchMore(isRetry: false);
 69	
 70	  /// The footer's "Tentar novamente" button — the one path allowed to
 71	  /// retry past a [MeusRegistrosLoaded.loadMoreFailed] of `true`
 72	  /// ([loadMore]'s own doc).
 73	  Future<void> retryLoadMore() => _fetchMore(isRetry: true);
 74	
 75	  Future<void> _fetchMore({required bool isRetry}) async {
 76	    final current = state;
 77	    if (current is! MeusRegistrosLoaded ||
 78	        current.nextCursor == null ||
 79	        current.isLoadingMore ||
 80	        (current.loadMoreFailed && !isRetry)) {
 81	      return;
 82	    }
 83	    final generation = _generation;
 84	    emit(current.copyWith(isLoadingMore: true, loadMoreFailed: false));
 85	    final result = await _repository.list(cursor: current.nextCursor);
 86	    if (isClosed || generation != _generation) {
 87	      return;
 88	    }
 89	    // Re-reads `state` rather than closing over `current` — defensive
 90	    // against `loadFirstPage()` having reset the state to something other
 91	    // than `MeusRegistrosLoaded` while this await was pending.
 92	    final latest = state;
 93	    if (latest is! MeusRegistrosLoaded) {
 94	      return;
 95	    }
 96	    result.match(
 97	      (failure) =>
 98	          emit(latest.copyWith(isLoadingMore: false, loadMoreFailed: true)),
 99	      (page) {
100	        // I/O matrix: "Next page appended, no dup ids" — defensive
101	        // de-duplication in case a cursor-boundary entry is ever repeated
102	        // by the server.
103	        final existingIds = latest.entries.map((entry) => entry.id).toSet();
104	        final newEntries = page.items
105	            .where((entry) => !existingIds.contains(entry.id))
106	            .toList();
107	        // Defensive guard against a degenerate server response: if every
108	        // item in this "successful" page was already present by id (zero
109	        // genuinely-new entries) yet the server still reports a non-null
110	        // `nextCursor`, treat the page as exhausted rather than trusting
111	        // that cursor — otherwise a misbehaving/stuck server cursor could
112	        // make the scroll listener keep re-triggering `loadMore()`
113	        // indefinitely with no progress.
114	        final nextCursor = newEntries.isEmpty ? null : page.nextCursor;
115	        emit(
116	          MeusRegistrosLoaded(
117	            entries: [...latest.entries, ...newEntries],
118	            nextCursor: nextCursor,
119	          ),
120	        );
121	      },
122	    );
123	  }
124	}

