14	/// Same tiny fake used by `app_router_test.dart`/`main_test.dart` — gives
15	/// synchronous control over both [SessionStatus] values and the
16	/// [statusStream] emission `ExpiryOverlayHost` subscribes to.
17	class _FakeSessionRepository implements SessionRepository {
18	  SessionStatus? _status;
19	  final _controller = StreamController<SessionStatus>.broadcast();
20	
21	  @override
22	  SessionStatus? get currentStatus => _status;
23	
24	  @override
25	  Stream<SessionStatus> get statusStream => _controller.stream;
26	
27	  @override
28	  Future<Either<Failure, Unit>> restoreSession() async => right(unit);
29	
30	  @override
31	  void markAuthenticated() => setStatus(SessionStatus.authenticated);
32	
33	  @override
34	  Future<void> dispose() => _controller.close();
35	
36	  void setStatus(SessionStatus status) {
37	    _status = status;
38	    _controller.add(status);
39	  }
40	}
41	
42	void main() {
43	  setUp(() {
44	    ConfirmationDialog.isOpen = false;
45	  });
46	
47	  testWidgets('an expired emission before the Navigator behind navigatorKey is '
48	      'mounted finds no overlay context, does not throw, and resets its '
49	      'one-shot guard so a later mount can still show the overlay', (
50	    tester,
51	  ) async {
52	    final fakeSessionRepository = _FakeSessionRepository();
53	    addTearDown(fakeSessionRepository.dispose);
54	    final router = GoRouter(
55	      routes: [
56	        GoRoute(path: '/', builder: (context, state) => const SizedBox()),
57	      ],
58	    );
59	    addTearDown(router.dispose);
60	    final navigatorKey = GlobalKey<NavigatorState>();
61	
62	    // First mount: `navigatorKey` matches nothing in this tree — no
63	    // `Navigator` anywhere uses it — simulating the Navigator not being
64	    // mounted yet when the expiry event arrives.
